rows={}
for ln in ROWS.strip().splitlines():
 f=ln.split('|'); assert len(f)==8,(f[0],len(f))
 rows[f[0]]=dict(zip(['topic','scope','execution','inputs','idea','boundary','evidence'],f[1:]))
entries=json.loads((ROOT/'research/catalogue-seed.json').read_text(encoding='utf-8'))
manifest={m['id']:m for m in json.loads((ROOT/'research/source-manifest.json').read_text(encoding='utf-8'))}
for e in entries:
 assert e['id'] in rows,e['id']
 e.update(rows[e['id']]); m=manifest.get(e['id'],{})
 p=ROOT/'research/sources'/((e['arxiv'] or e['id'])+'.txt')
 t=p.read_text(encoding='utf-8') if p.exists() else ''
 v=re.search(r'arXiv:(\d{4}\.\d+v\d+)',t)
 e['version']=v[1] if v else (e['arxiv'] or 'README 2026-10-24 快照')
 e['source_local']=str(p.relative_to(ROOT)).replace('\\','/')
 e['source_url']=('https://arxiv.org/html/'+e['version']) if e['arxiv'] else e['url']
 if m.get('status')=='fulltext-pdf': e['source_url']='https://arxiv.org/pdf/'+e['version']
 e['review_level']='方法与实验要点' if e['id'] not in ['A11','S01'] else ('官方工程说明' if e['id']=='A11' else '综述导航')
 if e['id'] in ['A01','A06','A08','A09','A10','A12']: e['review_level']='样章重点核查'
 e['type']='工程版本' if e['id']=='A11' else ('综述' if e['id']=='S01' else '论文')
 e['date']=('20'+e['arxiv'][:2]+'-'+e['arxiv'][2:4]) if e['arxiv'] else '2025-12'
 e['added']=e.get('addition_candidate',False)
 e['checked']='2026-10-24'
 e['source_sha256']=m.get('sha256','')
 e['cross_topics']=[]
cross={'A02':['01'],'A03':['07'],'A05':['01'],'A07':['01'],'A08':['02'],'A09':['02','08'],'A10':['02','07','08'],'A11':['02'],'A12':['04','08'],'B05':['01'],'B06':['04'],'B07':['04','05'],'C02':['05'],'C03':['03','07'],'C04':['05'],'D05':['01'],'E01':['05'],'E03':['06'],'E04':['02'],'E06':['07'],'F02':['05'],'F03':['01'],'F05':['01'],'F06':['01'],'F07':['04'],'G02':['07'],'G03':['02'],'G04':['05'],'G05':['06'],'H03':['01'],'H04':['08'],'H05':['10'],'H08':['05'],'N04':['01','04'],'N05':['04'],'N07':['06'],'N09':['01'],'N10':['08']}
for e in entries: e['cross_topics']=cross.get(e['id'],[])
(ROOT/'catalogue.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2),encoding='utf-8')
print('Curated',len(entries),'entries')
